// #5622b5 מסך פרטי חברה (шаг 1 мастера /onboarding) — «сервер в памяти» под ADMIN компании A.
// Данные профиля НЕ меняются: POST/PATCH company_profiles перехватываются (201, на сервер не уходят) и считаются в
// saves; любые прочие записи в Supabase (rest/storage) прерываются и считаются в blockedWrites. В GET company_profiles
// onboarding сбрасывается на шаг 1 («как у новой компании») — блок «למה הפרטים האלה חשובים?» виден только так.
// Своя копия (не импорт из onboarding-wizard), чтобы переписывание тестов мастера не ломало эти тесты.
import { Page, expect } from '@playwright/test';

const PROFILES = /\/rest\/v1\/company_profiles(\?|$)/;
const WRITE = (m: string) => !['GET', 'HEAD', 'OPTIONS'].includes(m);

export type DetailsServer = {
  /** Перехваченные записи company_profiles (на сервер не ушли). */
  saves: string[];
  /** Перехваченные прочие записи (должно быть 0). */
  blockedWrites: string[];
};

export async function mockFreshWizard(page: Page): Promise<DetailsServer> {
  const saves: string[] = [];
  const blockedWrites: string[] = [];

  await page.route(/supabase\.co\/(rest|storage)\/v1\//, async (route) => {
    const r = route.request();
    if (WRITE(r.method())) {
      blockedWrites.push(`${r.method()} ${r.url()}`);
      return route.abort();
    }
    return route.fallback();
  });

  await page.route(PROFILES, async (route) => {
    const r = route.request();
    if (WRITE(r.method())) {
      saves.push(`${r.method()} ${r.url()}`);
      return route.fulfill({ status: 201, body: '' });
    }
    const res = await route.fetch();
    const rows = (await res.json()) as Record<string, unknown>[];
    const patched = rows.map((row) => ({
      ...row,
      details: { ...((row.details as object) ?? {}), onboarding: { step: 0, completed: false, completedSteps: [] } },
    }));
    return route.fulfill({ response: res, json: patched });
  });

  return { saves, blockedWrites };
}

export const NEXT = 'המשך לשלב הבא';
export const SAVE_LATER = 'שמור והמשך מאוחר יותר';
export const ASIDE_TITLE = 'למה הפרטים האלה חשובים?';

/** Поля шага 1 по id (подтверждено 18.11, сборка lp1EzSMf). */
export const f = (page: Page) => ({
  reg: page.locator('#reg'),
  legal: page.locator('#legal'),
  founded: page.locator('#founded'),
  city: page.locator('#city'),
  contactName: page.locator('#contact-name'),
  contactRole: page.locator('#contact-role'),
  contactPhone: page.locator('#contact-phone'),
  contactEmail: page.locator('#contact-email'),
  aside: page.locator('aside').filter({ has: page.locator('#ob-aside-title') }),
});

/** Открыть шаг 1 мастера (профиль «как у новой компании») и дождаться формы. */
export async function openStep1(page: Page) {
  const server = await mockFreshWizard(page);
  await page.goto('/onboarding');
  await expect(page.locator('#ob-aside-title')).toBeVisible();
  await expect(f(page).legal).toBeVisible();
  return server;
}

/** Нормализация кавычек (״ " ' ׳ “ ” ' ") и пробелов — «тип кавычек не важен». */
export const norm = (s: string) =>
  s.replace(/[״“”„"]/g, '"').replace(/[׳‘’']/g, "'").replace(/\s+/g, ' ').trim();
